#' Carryover
#'
#' 
#' @param data .
#' @param l .
#' @param v .
#' @param lf .
#' @param lv .
#' @param lb .
#' @param lcv .
#' @param mf .
#' @param mv .
#' @param mb .
#' @param mcv .
#' @param hf .
#' @param hv .
#' @param hb .
#' @param hcv .
#' @param p .
#' @param rpd .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$text} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$abb} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$bg$cb} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$bg$scb} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$bg$c} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$ig$ci} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$ig$ic} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$mr$ct} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$mr$rp} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$mr$mrs} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$mr$rpc} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$t$ts} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$t$st} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$t$c} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$cv$t} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cv$c} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$summary} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' @export
Carryover <- function(
    data,
    l,
    v,
    lf = "Low",
    lv = 9,
    lb = 2,
    lcv = 8,
    mf = "Mid",
    mv = 50.5,
    mb = 4,
    mcv = 3,
    hf = "High",
    hv = 92,
    hb = 5,
    hcv = 2,
    p = 0.01,
    rpd = 1) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("Carryover requires jmvcore to be installed (restart may be required)")

    if ( ! missing(l)) l <- jmvcore::resolveQuo(jmvcore::enquo(l))
    if ( ! missing(v)) v <- jmvcore::resolveQuo(jmvcore::enquo(v))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(l), l, NULL),
            `if`( ! missing(v), v, NULL))


    options <- CarryoverOptions$new(
        l = l,
        v = v,
        lf = lf,
        lv = lv,
        lb = lb,
        lcv = lcv,
        mf = mf,
        mv = mv,
        mb = mb,
        mcv = mcv,
        hf = hf,
        hv = hv,
        hb = hb,
        hcv = hcv,
        p = p,
        rpd = rpd)

    analysis <- CarryoverClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

